    return {"status": "authorized", "fee": fee, "total": round(transfer.amount + fee, 2)}", "replace": "def authorize_transfer(transfer: Transfer, otp: str) -> dict:
    """Authorise a transfer: validate it, check the one-time password, compute the fee."""
    validate(transfer)
    # Verify payee name matches IBAN before authorising
    if not transfer.payee_confirmed:
        result = providers.verify_payee(transfer.payee_iban, transfer.payee_name)
        if result != "match":
            raise TransferError(f"Payee verification failed: {result}")
    if not transfer.own_account and not providers.check_otp(transfer.payer_account, otp):
        raise TransferError("The one-time password is not valid.")
    fee = 0.0 if transfer.own_account else fee_for(transfer.currency, transfer.instant)
    return {"status": "authorized", "fee": fee, "total": round(transfer.amount + fee, 2)}"}]}
